package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.algebra.AnnotationTripleRef;
import org.eclipse.rdf4j.query.algebra.ReifiedTripleRef;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.helpers.QueryAlgebraBindingAnalysis;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sparql.federation.RepositoryFederatedService;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class ReifiedServiceBindingTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI FIRST = VF.createIRI("urn:first");
	private static final IRI SECOND = VF.createIRI("urn:second");
	private static final IRI FIRST_REIFIER = VF.createIRI("urn:reifier:one");
	private static final IRI SECOND_REIFIER = VF.createIRI("urn:reifier:two");
	private static final IRI PREDICATE = VF.createIRI("urn:p");
	private static final IRI OBJECT = VF.createIRI("urn:o");
	private static final IRI NOTE = VF.createIRI("urn:note");
	private static final String REIFIED = "<< ?s <urn:p> ?o ~ ?r >> <urn:note> ?note";

	private SailRepository data;
	private RepositoryFederatedService endpoint;
	private SailRepository sender;

	@BeforeEach
	void setUp() {
		data = new SailRepository(new MemoryStore());
		try (var connection = data.getConnection()) {
			connection.add(FIRST, PREDICATE, OBJECT);
			connection.add(SECOND, PREDICATE, OBJECT);
			connection.add(FIRST_REIFIER, RDF.REIFIES, VF.createTripleTerm(FIRST, PREDICATE, OBJECT));
			connection.add(SECOND_REIFIER, RDF.REIFIES, VF.createTripleTerm(SECOND, PREDICATE, OBJECT));
			connection.add(FIRST_REIFIER, NOTE, VF.createLiteral("first"));
			connection.add(SECOND_REIFIER, NOTE, VF.createLiteral("second"));
		}
		endpoint = new RepositoryFederatedService(data, false);
		var store = new MemoryStore();
		store.setFederatedServiceResolver(ignored -> endpoint);
		sender = new SailRepository(store);
	}

	@AfterEach
	void tearDown() {
		sender.shutDown();
		endpoint.shutdown();
		data.shutDown();
	}

	@Test
	void reifiedServiceUsesPreparedComponentsAndReifier() {
		try (var connection = sender.getConnection()) {
			var query = connection
					.prepareTupleQuery("SELECT ?s ?r ?o ?note WHERE { SERVICE <urn:endpoint> { " + REIFIED + " } }");
			query.setBinding("s", FIRST);
			assertThat(QueryResults.asList(query.evaluate())).containsExactly(note(FIRST, FIRST_REIFIER, "first"));
			query.setBinding("s", VF.createIRI("urn:missing"));
			assertThat(QueryResults.asList(query.evaluate())).isEmpty();
			query.removeBinding("s");
			query.setBinding("r", SECOND_REIFIER);
			assertThat(QueryResults.asList(query.evaluate())).containsExactly(note(SECOND, SECOND_REIFIER, "second"));
			query.setBinding("s", FIRST);
			assertThat(QueryResults.asList(query.evaluate())).isEmpty();
			query.clearBindings();
			assertThat(QueryResults.asList(query.evaluate())).containsExactlyInAnyOrder(
					note(FIRST, FIRST_REIFIER, "first"),
					note(SECOND, SECOND_REIFIER, "second"));
		}
	}

	@Test
	void reifiedUnionRetainsDuplicateOptionalRows() {
		try (var connection = sender.getConnection()) {
			var query = connection.prepareTupleQuery("SELECT ?key ?note WHERE { VALUES ?key { 1 1 } OPTIONAL {"
					+ " SERVICE <urn:endpoint> { { " + REIFIED + " } UNION { BIND(\"ordinary\" AS ?note) } } } }");
			query.setBinding("s", FIRST);
			var rows = QueryResults.asList(query.evaluate());
			assertThat(rows).hasSize(4)
					.allSatisfy(row -> assertThat(row.getBindingNames()).containsExactlyInAnyOrder("key", "note"));
			assertThat(rows).extracting(row -> row.getValue("note"))
					.containsExactlyInAnyOrder(VF.createLiteral("first"), VF.createLiteral("first"),
							VF.createLiteral("ordinary"), VF.createLiteral("ordinary"));
		}
	}

	@Test
	void annotationInsideExistsUsesPreparedReifier() {
		String body = "BIND(EXISTS { <urn:first> <urn:p> <urn:o> ~ ?r . } AS ?found)";
		try (var remote = sender.getConnection(); var local = data.getConnection()) {
			var query = remote.prepareTupleQuery("SELECT ?found WHERE { SERVICE <urn:endpoint> { " + body + " } }");
			var direct = local.prepareTupleQuery("SELECT ?found WHERE { " + body + " }");
			for (var reifier : List.of(FIRST_REIFIER, SECOND_REIFIER, VF.createLiteral("not a resource"))) {
				direct.setBinding("r", reifier);
				query.setBinding("r", reifier);
				var expected = VF.createLiteral(FIRST_REIFIER.equals(reifier));
				assertThat(QueryResults.asList(direct.evaluate())).extracting(row -> row.getValue("found"))
						.containsExactly(expected);
				assertThat(QueryResults.asList(query.evaluate())).extracting(row -> row.getValue("found"))
						.containsExactly(expected);
			}
		}
	}

	@Test
	void reifierMetadataBelongsToTheSeparateStatementPattern() {
		for (var ref : List.of(new ReifiedTripleRef(), new AnnotationTripleRef())) {
			ref.setSubjectVar(Var.of("s"));
			ref.setPredicateVar(Var.of("p"));
			ref.setObjectVar(Var.of("o"));
			ref.setExprVar(Var.of("term"));
			ref.setReifVar(Var.of("reifier"));
			var analysis = QueryAlgebraBindingAnalysis.withBindingValues(ref, EmptyBindingSet.getInstance());
			assertThat(analysis.hasKnownBindingContract(ref)).isTrue();
			var outputs = analysis.outputFacts(ref);
			assertThat(outputs.possibleOutputs()).containsExactlyInAnyOrder("s", "p", "o", "term");
			assertThat(outputs.guaranteedOutputs()).containsExactlyInAnyOrder("s", "p", "o", "term");
			List<String> variables = new ArrayList<>();
			analysis.visitScoped(ref, analysis.rootContext(), (node, input) -> {
				if (node instanceof Var var) {
					variables.add(var.getName());
				}
				return true;
			});
			assertThat(variables).containsExactly("s", "p", "o", "term");
		}
	}

	private static BindingSet note(IRI subject, IRI reifier, String note) {
		var bindings = new MapBindingSet(4);
		bindings.addBinding("s", subject);
		bindings.addBinding("r", reifier);
		bindings.addBinding("o", OBJECT);
		bindings.addBinding("note", VF.createLiteral(note));
		return bindings;
	}
}
